        PropertyMetadata(name='has_energy_consumption_details', schema_name='hasEnergyConsumptionDetails', schema_url='https://schema.org/hasEnergyConsumptionDetails', ranges=('EnergyConsumptionDetails',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product',), external_domains=(), comment='Defines the energy efficiency Category (also known as "class" or "rating") for a product according to an international energy efficiency standard.', label='hasEnergyConsumptionDetails', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2670',)),
        PropertyMetadata(name='has_gs1_digital_link', schema_name='hasGS1DigitalLink', schema_url='https://schema.org/hasGS1DigitalLink', ranges=('URL',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('identifier',), domains=('Offer', 'Organization', 'Place', 'Product'), external_domains=(), comment='The <a href="https://www.gs1.org/standards/gs1-digital-link">GS1 digital link</a> associated with the object. This URL should conform to the particular requirements of digital links. The link should only contain the Application Identifiers (AIs) that are relevant for the entity being annotated, for instance a [[Product]] or an [[Organization]], and for the correct granularity. In particular, for products:<ul><li>A Digital Link that contains a serial number (AI <code>21</code>) should only be present on instances of [[IndividualProduct]]</li><li>A Digital Link that contains a lot number (AI <code>10</code>) should be annotated as [[SomeProducts]] if only products from that lot are sold, or [[IndividualProduct]] if there is only a specific product.</li><li>A Digital Link that contains a global model number (AI <code>8013</code>) should be attached to a [[Product]] or a [[ProductModel]].</li></ul> Other item types should be adapted similarly.', label='hasGS1DigitalLink', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3475',)),
        PropertyMetadata(name='has_measurement', schema_name='hasMeasurement', schema_url='https://schema.org/hasMeasurement', ranges=('QuantitativeValue',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Certification', 'Offer', 'Product', 'SizeSpecification'), external_domains=(), comment='A measurement of an item, For example, the inseam of pants, the wheel size of a bicycle, the gauge of a screw, or the carbon footprint measured for certification by an authority. Usually an exact measurement, but can also be a range of measurements for adjustable products, for example belts and ski bindings.', label='hasMeasurement', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2811',)),
        PropertyMetadata(name='has_merchant_return_policy', schema_name='hasMerchantReturnPolicy', schema_url='https://schema.org/hasMerchantReturnPolicy', ranges=('MerchantReturnPolicy',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('hasProductReturnPolicy',), equivalent_properties=(), subproperty_of=(), domains=('Offer', 'Organization', 'Product'), external_domains=(), comment='Specifies a MerchantReturnPolicy that may be applicable.', label='hasMerchantReturnPolicy', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2288',)),
        PropertyMetadata(name='has_product_return_policy', schema_name='hasProductReturnPolicy', schema_url='https://schema.org/hasProductReturnPolicy', ranges=('ProductReturnPolicy',), external_ranges=(), inverse_of=None, superseded_by='hasMerchantReturnPolicy', supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Organization', 'Product'), external_domains=(), comment='Indicates a ProductReturnPolicy that may be applicable.', label='hasProductReturnPolicy', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2288',)),
        PropertyMetadata(name='height', schema_name='height', schema_url='https://schema.org/height', ranges=('Distance', 'QuantitativeValue'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('MediaObject', 'OfferShippingDetails', 'Person', 'Product', 'ShippingConditions', 'VisualArtwork'), external_domains=(), comment='The height of the item.', label='height', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3617',)),
        PropertyMetadata(name='identifier', schema_name='identifier', schema_url='https://schema.org/identifier', ranges=('PropertyValue', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://purl.org/dc/terms/identifier', 'https://www.omg.org/spec/Commons/Identifiers/identifiedBy'), subproperty_of=(), domains=('Thing',), external_domains=(), comment='The identifier property represents any kind of identifier for any kind of [[Thing]], such as ISBNs, GTIN codes, UUIDs etc. Schema.org provides dedicated properties for representing many of these, either as textual strings or as URL (URI) links. See [background notes](/docs/datamodel.html#identifierBg) for more details.\n        ', label='identifier', contributors=(), sources=()),
        PropertyMetadata(name='image', schema_name='image', schema_url='https://schema.org/image', ranges=('ImageObject', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://ogp.me/ns#image',), subproperty_of=(), domains=('Thing',), external_domains=(), comment='An image of the item. This can be a [[URL]] or a fully described [[ImageObject]].', label='image', contributors=(), sources=()),
        PropertyMetadata(name='in_product_group_with_id', schema_name='inProductGroupWithID', schema_url='https://schema.org/inProductGroupWithID', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#variantId',), subproperty_of=(), domains=('Product',), external_domains=(), comment='Indicates the [[productGroupID]] for a [[ProductGroup]] that this product [[isVariantOf]]. ', label='inProductGroupWithID', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1797',)),
        PropertyMetadata(name='is_accessory_or_spare_part_for', schema_name='isAccessoryOrSparePartFor', schema_url='https://schema.org/isAccessoryOrSparePartFor', ranges=('Product',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product',), external_domains=(), comment='A pointer to another product (or multiple products) for which this product is an accessory or spare part.', label='isAccessoryOrSparePartFor', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='is_consumable_for', schema_name='isConsumableFor', schema_url='https://schema.org/isConsumableFor', ranges=('Product',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product',), external_domains=(), comment='A pointer to another product (or multiple products) for which this product is a consumable.', label='isConsumableFor', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='is_family_friendly', schema_name='isFamilyFriendly', schema_url='https://schema.org/isFamilyFriendly', ranges=('Boolean',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'Offer', 'Product'), external_domains=(), comment='Indicates whether this content is family friendly.', label='isFamilyFriendly', contributors=(), sources=()),
        PropertyMetadata(name='is_related_to', schema_name='isRelatedTo', schema_url='https://schema.org/isRelatedTo', ranges=('Product', 'Service'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#RelatedProduct',), subproperty_of=(), domains=('Product', 'Service'), external_domains=(), comment='A pointer to another, somehow related product (or multiple products).', label='isRelatedTo', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='is_similar_to', schema_name='isSimilarTo', schema_url='https://schema.org/isSimilarTo', ranges=('Product', 'Service'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#SubstituteProduct',), subproperty_of=(), domains=('Product', 'Service'), external_domains=(), comment='A pointer to another, functionally similar product (or multiple products).', label='isSimilarTo', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='is_variant_of', schema_name='isVariantOf', schema_url='https://schema.org/isVariantOf', ranges=('ProductGroup', 'ProductModel'), external_ranges=(), inverse_of='hasVariant', superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('http://www.w3.org/2004/02/skos/core#broader', 'https://www.omg.org/spec/Commons/Classifiers/exemplifies'), domains=('Product', 'ProductModel'), external_domains=(), comment='Indicates the kind of product that this is a variant of. In the case of [[ProductModel]], this is a pointer (from a ProductModel) to a base product from which this product is a variant. It is safe to infer that the variant inherits all product features from the base model, unless defined locally. This is not transitive. In the case of a [[ProductGroup]], the group description also serves as a template, representing a set of Products that vary on explicitly defined, specific dimensions only (so it defines both a set of variants, as well as which values distinguish amongst those variants). When used with [[ProductGroup]], this property can apply to any [[Product]] included in the group.', label='isVariantOf', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='item_condition', schema_name='itemCondition', schema_url='https://schema.org/itemCondition', ranges=('OfferItemCondition',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Demand', 'MerchantReturnPolicy', 'Offer', 'Product'), external_domains=(), comment='A predefined value from OfferItemCondition specifying the condition of the product or service, or the products or services included in the offer. Also used for product return policies to specify the condition of products accepted for returns.', label='itemCondition', contributors=(), sources=()),
        PropertyMetadata(name='keywords', schema_name='keywords', schema_url='https://schema.org/keywords', ranges=('DefinedTerm', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'Event', 'Organization', 'Place', 'Product'), external_domains=(), comment='Keywords or tags used to describe some item. Multiple textual entries in a keywords list are typically delimited by commas, or by repeating the property.', label='keywords', contributors=(), sources=()),
        PropertyMetadata(name='known_vehicle_damages', schema_name='knownVehicleDamages', schema_url='https://schema.org/knownVehicleDamages', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='A textual description of known damages, both repaired and unrepaired.', label='knownVehicleDamages', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='logo', schema_name='logo', schema_url='https://schema.org/logo', ranges=('ImageObject', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#logoReferencedDocument',), subproperty_of=('image',), domains=('Brand', 'Certification', 'Organization', 'Place', 'Product', 'Service'), external_domains=(), comment='An associated logo.', label='logo', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='main_entity_of_page', schema_name='mainEntityOfPage', schema_url='https://schema.org/mainEntityOfPage', ranges=('CreativeWork', 'URL'), external_ranges=(), inverse_of='mainEntity', superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Thing',), external_domains=(), comment='Indicates a page (or other CreativeWork) for which this thing is the main entity being described. See [background notes](/docs/datamodel.html#mainEntityBackground) for details.', label='mainEntityOfPage', contributors=(), sources=()),
        PropertyMetadata(name='manufacturer', schema_name='manufacturer', schema_url='https://schema.org/manufacturer', ranges=('Organization',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#manufacturerParty', 'https://ref.gs1.org/voc/manufacturer'), subproperty_of=('https://spec.edmcouncil.org/fibo/ontology/FND/ProductsAndServices/ProductsAndServices/isProvisionedBy',), domains=('Product',), external_domains=(), comment='The manufacturer of the product.', label='manufacturer', contributors=(), sources=()),
        PropertyMetadata(name='material', schema_name='material', schema_url='https://schema.org/material', ranges=('Product', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'Product'), external_domains=(), comment='A material that something is made from, e.g. leather, wool, cotton, paper.', label='material', contributors=(), sources=()),
        PropertyMetadata(name='meets_emission_standard', schema_name='meetsEmissionStandard', schema_url='https://schema.org/meetsEmissionStandard', ranges=('QualitativeValue', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='Indicates that the vehicle meets the respective emission standard.', label='meetsEmissionStandard', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='mileage_from_odometer', schema_name='mileageFromOdometer', schema_url='https://schema.org/mileageFromOdometer', ranges=('QuantitativeValue',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The total distance travelled by the particular vehicle since its initial production, as read from its odometer.\\n\\nTypical unit code(s): KMT for kilometers, SMI for statute miles.', label='mileageFromOdometer', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='mobile_url', schema_name='mobileUrl', schema_url='https://schema.org/mobileUrl', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Offer', 'Product'), external_domains=(), comment='The [[mobileUrl]] property is provided for specific situations in which data consumers need to determine whether one of several provided URLs is a dedicated \'mobile site\'.\n\nTo discourage over-use, and reflecting intial usecases, the property is expected only on [[Product]] and [[Offer]], rather than [[Thing]]. The general trend in web technology is towards [responsive design](https://en.wikipedia.org/wiki/Responsive_web_design) in which content can be flexibly adapted to a wide range of browsing environments. Pages and sites referenced with the long-established [[url]] property should ideally also be usable on a wide variety of devices, including mobile phones. In most cases, it would be pointless and counter productive to attempt to update all [[url]] markup to use [[mobileUrl]] for more mobile-oriented pages. The property is intended for the case when items (primarily [[Product]] and [[Offer]]) have extra URLs hosted on an additional "mobile site" alongside the main one. It should not be taken as an endorsement of this publication style.\n    ', label='mobileUrl', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3134',)),
        PropertyMetadata(name='model', schema_name='model', schema_url='https://schema.org/model', ranges=('ProductModel', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#ModelName',), subproperty_of=('https://www.omg.org/spec/Commons/Classifiers/isClassifiedBy',), domains=('Product',), external_domains=(), comment='The model of the product. Use with the URL of a ProductModel or a textual representation of the model identifier. The URL of the ProductModel can be from an external source. It is recommended to additionally provide strong product identifiers via the gtin8/gtin13/gtin14 and mpn properties.', label='model', contributors=(), sources=()),
        PropertyMetadata(name='model_date', schema_name='modelDate', schema_url='https://schema.org/modelDate', ranges=('Date',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The release date of a vehicle model (often used to differentiate versions of the same make and model).', label='modelDate', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='mpn', schema_name='mpn', schema_url='https://schema.org/mpn', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#manufacturerAssignedId',), subproperty_of=(), domains=('Demand', 'Offer', 'Product'), external_domains=(), comment='The Manufacturer Part Number (MPN) of the product, or the product to which the offer refers.', label='mpn', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='name', schema_name='name', schema_url='https://schema.org/name', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://ogp.me/ns#title', 'http://purl.org/dc/terms/title', 'https://www.omg.org/spec/Commons/Text/hasName'), subproperty_of=('http://www.w3.org/2000/01/rdf-schema#label',), domains=('Thing',), external_domains=(), comment='The name of the item.', label='name', contributors=(), sources=()),
        PropertyMetadata(name='negative_notes', schema_name='negativeNotes', schema_url='https://schema.org/negativeNotes', ranges=('ItemList', 'ListItem', 'Text', 'WebContent'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product', 'Review'), external_domains=(), comment='Provides negative considerations regarding something, most typically in pro/con lists for reviews (alongside [[positiveNotes]]). For symmetry \n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described. Since product descriptions \ntend to emphasise positive claims, it may be relatively unusual to find [[negativeNotes]] used in this way. Nevertheless for the sake of symmetry, [[negativeNotes]] can be used on [[Product]].\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most negative is at the beginning of the list).', label='negativeNotes', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2832',)),
        PropertyMetadata(name='nsn', schema_name='nsn', schema_url='https://schema.org/nsn', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#nSNId',), subproperty_of=('identifier', 'https://www.omg.org/spec/Commons/Identifiers/identifiedBy'), domains=('Product',), external_domains=(), comment='Indicates the [NATO stock number](https://en.wikipedia.org/wiki/NATO_Stock_Number) (nsn) of a [[Product]]. ', label='nsn', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2126',)),
        PropertyMetadata(name='number_of_airbags', schema_name='numberOfAirbags', schema_url='https://schema.org/numberOfAirbags', ranges=('Number', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The number or type of airbags in the vehicle.', label='numberOfAirbags', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='number_of_axles', schema_name='numberOfAxles', schema_url='https://schema.org/numberOfAxles', ranges=('Number', 'QuantitativeValue'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The number of axles.\\n\\nTypical unit code(s): C62.', label='numberOfAxles', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='number_of_doors', schema_name='numberOfDoors', schema_url='https://schema.org/numberOfDoors', ranges=('Number', 'QuantitativeValue'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The number of doors.\\n\\nTypical unit code(s): C62.', label='numberOfDoors', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='number_of_forward_gears', schema_name='numberOfForwardGears', schema_url='https://schema.org/numberOfForwardGears', ranges=('Number', 'QuantitativeValue'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The total number of forward gears available for the transmission system of the vehicle.\\n\\nTypical unit code(s): C62.', label='numberOfForwardGears', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='number_of_previous_owners', schema_name='numberOfPreviousOwners', schema_url='https://schema.org/numberOfPreviousOwners', ranges=('Number', 'QuantitativeValue'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The number of owners of the vehicle, including the current one.\\n\\nTypical unit code(s): C62.', label='numberOfPreviousOwners', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='offers', schema_name='offers', schema_url='https://schema.org/offers', ranges=('Demand', 'Offer'), external_ranges=(), inverse_of='itemOffered', superseded_by=None, supersedes=(), equivalent_properties=('https://spec.edmcouncil.org/fibo/ontology/FND/ProductsAndServices/ProductsAndServices/isProductOf',), subproperty_of=(), domains=('AggregateOffer', 'CreativeWork', 'EducationalOccupationalProgram', 'Event', 'MenuItem', 'Product', 'Service', 'Trip'), external_domains=(), comment='An offer to provide this item&#x2014;for example, an offer to sell a product, rent the DVD of a movie, perform a service, or give away tickets to an event. Use [[businessFunction]] to indicate the kind of transaction offered, i.e. sell, lease, etc. This property can also be used to describe a [[Demand]]. While this property is listed as expected on a number of common types, it can be used in others. In that case, using a second type, such as Product or a subtype of Product, can clarify the nature of the offer.\n      ', label='offers', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2289',)),
        PropertyMetadata(name='owner', schema_name='owner', schema_url='https://schema.org/owner', ranges=('Organization', 'Person'), external_ranges=(), inverse_of='owns', superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Thing',), external_domains=(), comment='A person or organization who owns this Thing.', label='owner', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/4603',)),
        PropertyMetadata(name='pattern', schema_name='pattern', schema_url='https://schema.org/pattern', ranges=('DefinedTerm', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#printDesignDescription',), subproperty_of=(), domains=('CreativeWork', 'Product'), external_domains=(), comment="A pattern that something has, for example 'polka dot', 'striped', 'Canadian flag'. Values are typically expressed as text, although links to controlled value schemes are also supported.", label='pattern', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1797',)),
        PropertyMetadata(name='payload', schema_name='payload', schema_url='https://schema.org/payload', ranges=('QuantitativeValue',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Vehicle',), external_domains=(), comment='The permitted weight of passengers and cargo, EXCLUDING the weight of the empty vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: Many databases specify the permitted TOTAL weight instead, which is the sum of [[weight]] and [[payload]]\\n* Note 2: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 3: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 4: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.', label='payload', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='positive_notes', schema_name='positiveNotes', schema_url='https://schema.org/positiveNotes', ranges=('ItemList', 'ListItem', 'Text', 'WebContent'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product', 'Review'), external_domains=(), comment='Provides positive considerations regarding something, for example product highlights or (alongside [[negativeNotes]]) pro/con lists for reviews.\n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described.\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most positive is at the beginning of the list).', label='positiveNotes', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2832',)),
        PropertyMetadata(name='potential_action', schema_name='potentialAction', schema_url='https://schema.org/potentialAction', ranges=('Action',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Thing',), external_domains=(), comment="Indicates a potential Action, which describes an idealized action in which this thing would play an 'object' role.", label='potentialAction', contributors=(), sources=()),
        PropertyMetadata(name='product_id', schema_name='productID', schema_url='https://schema.org/productID', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('identifier',), domains=('Product',), external_domains=(), comment='The product identifier, such as ISBN. For example: ``` meta itemprop="productID" content="isbn:123-456-789" ```.', label='productID', contributors=(), sources=()),
        PropertyMetadata(name='production_date', schema_name='productionDate', schema_url='https://schema.org/productionDate', ranges=('Date',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#ProductionDate',), subproperty_of=(), domains=('Product', 'Vehicle'), external_domains=(), comment='The date of production of the item, e.g. vehicle.', label='productionDate', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='purchase_date', schema_name='purchaseDate', schema_url='https://schema.org/purchaseDate', ranges=('Date',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product', 'Vehicle'), external_domains=(), comment='The date the item, e.g. vehicle, was purchased by the current owner.', label='purchaseDate', contributors=('https://schema.org/docs/collab/Automotive_Ontology_Working_Group',), sources=()),
        PropertyMetadata(name='release_date', schema_name='releaseDate', schema_url='https://schema.org/releaseDate', ranges=('Date',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#ProductAvailabilityDate',), subproperty_of=(), domains=('Product',), external_domains=(), comment='The release date of a product or product model. This can be used to distinguish the exact variant of a product.', label='releaseDate', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
