    schema_id: str | None = Field(default=None, alias='@id')
    schema_type: Literal['Vehicle'] = Field(default='Vehicle', alias='@type', frozen=True)
    acceleration_time: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='accelerationTime', description='The time needed to accelerate the vehicle from a given start velocity to a given target velocity.\\n\\nTypical unit code(s): SEC for seconds\\n\\n* Note: There are unfortunately no standard unit codes for seconds/0..100 km/h or seconds/0..60 mph. Simply use "SEC" for seconds and indicate the velocities in the [[name]] of the [[QuantitativeValue]], or use [[valueReference]] with a [[QuantitativeValue]] of 0..60 mph or 0..100 km/h to specify the reference speeds.')
    body_type: QualitativeValue | BedType | DriveWheelConfigurationValue | SizeSpecification | SteeringPositionValue | Text | URL | list[QualitativeValue | BedType | DriveWheelConfigurationValue | SizeSpecification | SteeringPositionValue | Text | URL] | None = Field(default=None, alias='bodyType', description='Indicates the design and body style of the vehicle (e.g. station wagon, hatchback, etc.).')
    call_sign: Text | list[Text] | None = Field(default=None, alias='callSign', description='A [callsign](https://en.wikipedia.org/wiki/Call_sign), as used in broadcasting and radio communications to identify people, radio and TV stations, or vehicles.')
    cargo_volume: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='cargoVolume', description='The available volume for cargo or luggage. For automobiles, this is usually the trunk volume.\\n\\nTypical unit code(s): LTR for liters, FTQ for cubic foot/feet\\n\\nNote: You can use [[minValue]] and [[maxValue]] to indicate ranges.')
    date_vehicle_first_registered: Date | list[Date] | None = Field(default=None, alias='dateVehicleFirstRegistered', description='The date of the first registration of the vehicle with the respective public authorities.')
    drive_wheel_configuration: DriveWheelConfigurationValue | Text | list[DriveWheelConfigurationValue | Text] | None = Field(default=None, alias='driveWheelConfiguration', description="The drive wheel configuration, i.e. which roadwheels will receive torque from the vehicle's engine via the drivetrain.")
    emissions_co2: Number | list[Number] | None = Field(default=None, alias='emissionsCO2', description='The CO2 emissions in g/km. When used in combination with a QuantitativeValue, put "g/km" into the unitText property of that value, since there is no UN/CEFACT Common Code for "g/km".')
    fuel_capacity: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='fuelCapacity', description='The capacity of the fuel tank or in the case of electric cars, the battery. If there are multiple components for storage, this should indicate the total of all storage of the same type.\\n\\nTypical unit code(s): LTR for liters, GLL of US gallons, GLI for UK / imperial gallons, AMH for ampere-hours (for electrical vehicles).')
    fuel_consumption: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='fuelConsumption', description='The amount of fuel consumed for traveling a particular distance or temporal duration with the given vehicle (e.g. liters per 100 km).\\n\\n* Note 1: There are unfortunately no standard unit codes for liters per 100 km.  Use [[unitText]] to indicate the unit of measurement, e.g. L/100 km.\\n* Note 2: There are two ways of indicating the fuel consumption, [[fuelConsumption]] (e.g. 8 liters per 100 km) and [[fuelEfficiency]] (e.g. 30 miles per gallon). They are reciprocal.\\n* Note 3: Often, the absolute value is useful only when related to driving speed ("at 80 km/h") or usage pattern ("city traffic"). You can use [[valueReference]] to link the value for the fuel consumption to another value.')
    fuel_efficiency: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='fuelEfficiency', description='The distance traveled per unit of fuel used; most commonly miles per gallon (mpg) or kilometers per liter (km/L).\\n\\n* Note 1: There are unfortunately no standard unit codes for miles per gallon or kilometers per liter. Use [[unitText]] to indicate the unit of measurement, e.g. mpg or km/L.\\n* Note 2: There are two ways of indicating the fuel consumption, [[fuelConsumption]] (e.g. 8 liters per 100 km) and [[fuelEfficiency]] (e.g. 30 miles per gallon). They are reciprocal.\\n* Note 3: Often, the absolute value is useful only when related to driving speed ("at 80 km/h") or usage pattern ("city traffic"). You can use [[valueReference]] to link the value for the fuel economy to another value.')
    fuel_type: QualitativeValue | BedType | DriveWheelConfigurationValue | SizeSpecification | SteeringPositionValue | Text | URL | list[QualitativeValue | BedType | DriveWheelConfigurationValue | SizeSpecification | SteeringPositionValue | Text | URL] | None = Field(default=None, alias='fuelType', description='The type of fuel suitable for the engine or engines of the vehicle. If the vehicle has only one engine, this property can be attached directly to the vehicle.')
    known_vehicle_damages: Text | list[Text] | None = Field(default=None, alias='knownVehicleDamages', description='A textual description of known damages, both repaired and unrepaired.')
    meets_emission_standard: QualitativeValue | BedType | DriveWheelConfigurationValue | SizeSpecification | SteeringPositionValue | Text | URL | list[QualitativeValue | BedType | DriveWheelConfigurationValue | SizeSpecification | SteeringPositionValue | Text | URL] | None = Field(default=None, alias='meetsEmissionStandard', description='Indicates that the vehicle meets the respective emission standard.')
    mileage_from_odometer: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='mileageFromOdometer', description='The total distance travelled by the particular vehicle since its initial production, as read from its odometer.\\n\\nTypical unit code(s): KMT for kilometers, SMI for statute miles.')
    model_date: Date | list[Date] | None = Field(default=None, alias='modelDate', description='The release date of a vehicle model (often used to differentiate versions of the same make and model).')
    number_of_airbags: Number | Text | list[Number | Text] | None = Field(default=None, alias='numberOfAirbags', description='The number or type of airbags in the vehicle.')
    number_of_axles: Number | QuantitativeValue | list[Number | QuantitativeValue] | None = Field(default=None, alias='numberOfAxles', description='The number of axles.\\n\\nTypical unit code(s): C62.')
    number_of_doors: Number | QuantitativeValue | list[Number | QuantitativeValue] | None = Field(default=None, alias='numberOfDoors', description='The number of doors.\\n\\nTypical unit code(s): C62.')
    number_of_forward_gears: Number | QuantitativeValue | list[Number | QuantitativeValue] | None = Field(default=None, alias='numberOfForwardGears', description='The total number of forward gears available for the transmission system of the vehicle.\\n\\nTypical unit code(s): C62.')
    number_of_previous_owners: Number | QuantitativeValue | list[Number | QuantitativeValue] | None = Field(default=None, alias='numberOfPreviousOwners', description='The number of owners of the vehicle, including the current one.\\n\\nTypical unit code(s): C62.')
    payload: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='payload', description='The permitted weight of passengers and cargo, EXCLUDING the weight of the empty vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: Many databases specify the permitted TOTAL weight instead, which is the sum of [[weight]] and [[payload]]\\n* Note 2: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 3: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 4: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.')
    production_date: Date | list[Date] | None = Field(default=None, alias='productionDate', description='The date of production of the item, e.g. vehicle.')
    purchase_date: Date | list[Date] | None = Field(default=None, alias='purchaseDate', description='The date the item, e.g. vehicle, was purchased by the current owner.')
    seating_capacity: Number | QuantitativeValue | list[Number | QuantitativeValue] | None = Field(default=None, alias='seatingCapacity', description='The number of persons that can be seated (e.g. in a vehicle), both in terms of the physical space available, and in terms of limitations set by law.\\n\\nTypical unit code(s): C62 for persons.')
    speed: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='speed', description='The speed range of the vehicle. If the vehicle is powered by an engine, the upper limit of the speed range (indicated by [[maxValue]]) should be the maximum speed achievable under regular conditions.\\n\\nTypical unit code(s): KMH for km/h, HM for mile per hour (0.447 04 m/s), KNT for knot\\n\\n*Note 1: Use [[minValue]] and [[maxValue]] to indicate the range. Typically, the minimal value is zero.\\n* Note 2: There are many different ways of measuring the speed range. You can link to information about how the given value has been determined using the [[valueReference]] property.')
    steering_position: SteeringPositionValue | list[SteeringPositionValue] | None = Field(default=None, alias='steeringPosition', description='The position of the steering wheel or similar device (mostly for cars).')
    stupid_property: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='stupidProperty', description='This is a StupidProperty! - for testing only.')
    tongue_weight: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='tongueWeight', description='The permitted vertical load (TWR) of a trailer attached to the vehicle. Also referred to as Tongue Load Rating (TLR) or Vertical Load Rating (VLR).\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.')
    trailer_weight: QuantitativeValue | list[QuantitativeValue] | None = Field(default=None, alias='trailerWeight', description='The permitted weight of a trailer attached to the vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.')
    vehicle_configuration: Text | list[Text] | None = Field(default=None, alias='vehicleConfiguration', description="A short text indicating the configuration of the vehicle, e.g. '5dr hatchback ST 2.5 MT 225 hp' or 'limited edition'.")
    vehicle_engine: EngineSpecification | list[EngineSpecification] | None = Field(default=None, alias='vehicleEngine', description='Information about the engine or engines of the vehicle.')
    vehicle_identification_number: Text | list[Text] | None = Field(default=None, alias='vehicleIdentificationNumber', description='The Vehicle Identification Number (VIN) is a unique serial number used by the automotive industry to identify individual motor vehicles.')
    vehicle_interior_color: Text | list[Text] | None = Field(default=None, alias='vehicleInteriorColor', description='The color or color combination of the interior of the vehicle.')
    vehicle_interior_type: Text | list[Text] | None = Field(default=None, alias='vehicleInteriorType', description='The type or material of the interior of the vehicle (e.g. synthetic fabric, leather, wood, etc.). While most interior types are characterized by the material used, an interior type can also be based on vehicle usage or target audience.')
    vehicle_model_date: Date | list[Date] | None = Field(default=None, alias='vehicleModelDate', description='The release date of a vehicle model (often used to differentiate versions of the same make and model).')
    vehicle_seating_capacity: Number | QuantitativeValue | list[Number | QuantitativeValue] | None = Field(default=None, alias='vehicleSeatingCapacity', description='The number of passengers that can be seated in the vehicle, both in terms of the physical space available, and in terms of limitations set by law.\\n\\nTypical unit code(s): C62 for persons.')
    vehicle_special_usage: CarUsageType | Text | list[CarUsageType | Text] | None = Field(default=None, alias='vehicleSpecialUsage', description='Indicates whether the vehicle has been used for special purposes, like commercial rental, driving school, or as a taxi. The legislation in many countries requires this information to be revealed when offering a car for sale.')
